import "./Hero.css";
import { useState } from "react";

// Example monastery images (replace with your PNGs/JPGs)
import hero1 from "./hero1.png";
import hero2 from "./hero2.png";
import hero3 from "./hero3.png";
import hero4 from "./hero4.png";
import hero5 from "./hero5.png";
import hero6 from "./hero6.png";

export default function Hero() {
  // Monasteries data
  const [photos] = useState([
    { id: 1, src: hero1, title: "Rumtek Monastery", desc: "Famous for golden stupa and Kagyu lineage." },
    { id: 2, src: hero2, title: "Pemayangtse Monastery", desc: "One of the oldest Nyingma monasteries." },
    { id: 3, src: hero3, title: "Tashiding Monastery", desc: "Known as the heart of Sikkim’s Buddhism." },
    { id: 4, src: hero4, title: "Phodong Monastery", desc: "Rich murals and 18th century legacy." },
    { id: 5, src: hero5, title: "Enchey Monastery", desc: "Sacred place of tantric master Lama Drupthob." },
    { id: 6, src: hero6, title: "Ralong Monastery", desc: "Beautiful paintings and annual festivals." },
  ]);

  // State for selected monastery (modal)
  const [selected, setSelected] = useState(null);

  return (
    <section className="hero-section" id="home">
      <h2 className="hero-heading">Explore Sikkim’s Sacred Monasteries</h2>
      <p className="hero-subheading">
        Hover over each monastery to learn more. Click to explore further.
      </p>

      {/* Photo Grid */}
      <div className="photo-grid">
        {photos.map((photo) => (
          <div
            key={photo.id}
            className="photo-card"
            onClick={() => setSelected(photo)}
          >
            <img src={photo.src} alt={photo.title} />
            <div className="overlay">
              <h3>{photo.title}</h3>
              <p>{photo.desc}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Modal for selected photo */}
      {selected && (
        <div className="modal">
          <div className="modal-content">
            <button className="close-btn" onClick={() => setSelected(null)}>
              ✖
            </button>
            <img src={selected.src} alt={selected.title} />
            <h3>{selected.title}</h3>
            <p>{selected.desc}</p>
          </div>
        </div>
      )}
    </section>
  );
}
